create or replace function public.create_organization(p_name text, p_slug text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_user uuid := auth.uid(); v_name text := nullif(trim(p_name),''); v_slug text := nullif(trim(lower(coalesce(p_slug,''))),''); v_org public.organizations%rowtype; v_trial timestamptz := now()+interval '14 days'; begin if v_user is null then raise exception 'Authentication required'; end if; if v_name is null or length(v_name)<2 or length(v_name)>120 then raise exception 'Invalid organization name'; end if; if v_slug is null then v_slug:=regexp_replace(lower(unaccent(v_name)),'[^a-z0-9]+','-','g'); else v_slug:=regexp_replace(lower(unaccent(v_slug)),'[^a-z0-9]+','-','g'); end if; v_slug:=trim(both '-' from v_slug); if exists(select 1 from public.organizations where slug=v_slug) then v_slug:=v_slug||'-'||substr(md5(clock_timestamp()::text),1,6); end if; insert into public.organizations(name,slug,status,plan_code,trial_ends_at) values(v_name,v_slug,'trial','starter',v_trial) returning * into v_org; insert into public.organization_members(organization_id,user_id,role,status,permissions,joined_at) values(v_org.id,v_user,'owner','active','{}',now()); insert into public.saas_subscriptions(organization_id,plan_code,status,billing_cycle,trial_ends_at,current_period_start,current_period_end) values(v_org.id,'starter','trialing','monthly',v_trial,now(),v_trial); update public.profiles set active_organization_id=v_org.id,updated_at=now() where id=v_user; return jsonb_build_object('id',v_org.id,'name',v_org.name,'slug',v_org.slug,'status',v_org.status,'plan_code','starter','trial_ends_at',v_trial,'role','owner'); end $$;